"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import {
  ToggleLeft,
  ToggleRight,
  Settings,
  AlertTriangle,
  ShieldCheck,
  Mail,
  Database,
} from "lucide-react";

interface FeatureFlag {
  id: string;
  name: string;
  description: string;
  isEnabled: boolean;
  category: "SYSTEM" | "USER" | "BETA";
  icon: any;
}

export default function FeaturesPage() {
  const [features, setFeatures] = useState<FeatureFlag[]>([
    {
      id: "f1",
      name: "Maintenance Mode",
      description:
        "Put the entire system into maintenance mode. Only admins can access.",
      isEnabled: false,
      category: "SYSTEM",
      icon: AlertTriangle,
    },
    {
      id: "f2",
      name: "New Dashboard Layout",
      description: "Enable the experimental V2 dashboard layout for all users.",
      isEnabled: true,
      category: "BETA",
      icon: Settings,
    },
    {
      id: "f3",
      name: "Two-Factor Authentication",
      description: "Enforce 2FA for all staff and lecturer accounts.",
      isEnabled: true,
      category: "USER",
      icon: ShieldCheck,
    },
    {
      id: "f4",
      name: "Email Notifications",
      description: "Send automated email notifications for system events.",
      isEnabled: true,
      category: "SYSTEM",
      icon: Mail,
    },
    {
      id: "f5",
      name: "Legacy Database Sync",
      description: "Sync data with the old Oracle database every hour.",
      isEnabled: false,
      category: "SYSTEM",
      icon: Database,
    },
  ]);

  const toggleFeature = (id: string) => {
    setFeatures(
      features.map((f) =>
        f.id === id ? { ...f, isEnabled: !f.isEnabled } : f,
      ),
    );
  };

  return (
    <div className="mx-auto max-w-5xl p-8">
      <header className="mb-10">
        <h1 className="text-3xl font-bold text-gray-800">Feature Control</h1>
        <p className="mt-1 text-gray-500">
          Manage feature flags and system toggles
        </p>
      </header>

      <div className="space-y-6">
        {features.map((feature, index) => {
          const Icon = feature.icon;
          return (
            <motion.div
              key={feature.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.05 }}
              className={`flex items-center justify-between rounded-xl border p-6 transition-all duration-200 ${
                feature.isEnabled
                  ? "border-blue-200 bg-white shadow-md shadow-blue-500/5"
                  : "border-gray-200 bg-gray-50 opacity-90"
              } `}
            >
              <div className="flex items-start gap-4">
                <div
                  className={`rounded-lg p-3 ${feature.isEnabled ? "bg-blue-100 text-blue-600" : "bg-gray-200 text-gray-500"}`}
                >
                  <Icon size={24} />
                </div>
                <div>
                  <div className="flex items-center gap-3">
                    <h3 className="text-lg font-bold text-gray-800">
                      {feature.name}
                    </h3>
                    <span
                      className={`rounded border px-2 py-0.5 text-[10px] font-bold uppercase ${
                        feature.category === "SYSTEM"
                          ? "border-red-100 bg-red-50 text-red-600"
                          : feature.category === "BETA"
                            ? "border-purple-100 bg-purple-50 text-purple-600"
                            : "border-green-100 bg-green-50 text-green-600"
                      } `}
                    >
                      {feature.category}
                    </span>
                  </div>
                  <p className="mt-1 max-w-lg text-sm text-gray-500">
                    {feature.description}
                  </p>
                </div>
              </div>

              <button
                onClick={() => toggleFeature(feature.id)}
                className={`relative inline-flex h-8 w-14 items-center rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 ${feature.isEnabled ? "bg-blue-600" : "bg-gray-300"} `}
              >
                <span className="sr-only">Enable {feature.name}</span>
                <span
                  className={`inline-block h-6 w-6 transform rounded-full bg-white transition-transform duration-200 ease-in-out ${feature.isEnabled ? "translate-x-7" : "translate-x-1"} `}
                />
              </button>
            </motion.div>
          );
        })}
      </div>

      <div className="mt-8 flex items-start gap-3 rounded-lg border border-yellow-200 bg-yellow-50 p-4">
        <AlertTriangle className="mt-0.5 shrink-0 text-yellow-600" size={20} />
        <div>
          <h4 className="text-sm font-bold text-yellow-800">Caution</h4>
          <p className="mt-0.5 text-sm text-yellow-700">
            Toggling "System" features may result in temporary service
            interruptions. Please ensure you have approval before making
            changes.
          </p>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Info, Calculator, Download, AlertTriangle, ExternalLink, Check } from 'lucide-react';

interface Course {
  id: string;
  courseId: string;
  courseName: string;
  credits: number;
  group: string;
  selected: boolean;
}

interface WithdrawalRecord {
  id: number;
  requestId: string;
  courseDetails: string;
  credits: number;
  submissionDate: string;
  status: 'Pending' | 'Approved' | 'Rejected';
}

export function CourseWithdrawal() {
  const [courses, setCourses] = useState<Course[]>([
    { id: '1', courseId: 'CO1005', courseName: 'Introduction to Computer Programming', credits: 4, group: 'CC02', selected: false },
    { id: '2', courseId: 'CO1023', courseName: 'Computer Networks', credits: 4, group: 'CC01', selected: false },
    { id: '3', courseId: 'PH1003', courseName: 'Physics 1', credits: 3, group: 'CC17', selected: false },
    { id: '4', courseId: 'MT1003', courseName: 'Calculus 1', credits: 4, group: 'CC21', selected: false },
    { id: '5', courseId: 'CH1003', courseName: 'General Chemistry', credits: 3, group: 'CC05', selected: false },
  ]);

  const [agreedToTerms, setAgreedToTerms] = useState(false);

  const [records] = useState<WithdrawalRecord[]>([
    {
      id: 1,
      requestId: 'CW2025120001',
      courseDetails: 'CO1001 - Introduction to Computer Science (CC03)',
      credits: 4,
      submissionDate: '10/12/2025',
      status: 'Approved',
    },
    {
      id: 2,
      requestId: 'CW2025110045',
      courseDetails: 'MT1005 - Linear Algebra (CC12)',
      credits: 3,
      submissionDate: '05/11/2025',
      status: 'Pending',
    },
  ]);

  const minimumRequiredCredits = 12;
  const currentEnrolledCredits = courses.reduce((sum, course) => sum + course.credits, 0);
  const withdrawalCredits = courses.filter(c => c.selected).reduce((sum, course) => sum + course.credits, 0);
  const creditsAfterWithdrawal = currentEnrolledCredits - withdrawalCredits;
  const isUnderMinimum = creditsAfterWithdrawal < minimumRequiredCredits;

  const toggleCourseSelection = (courseId: string) => {
    setCourses(courses.map(course => 
      course.id === courseId ? { ...course, selected: !course.selected } : course
    ));
  };

  const handleConfirmWithdrawal = () => {
    const selectedCourses = courses.filter(c => c.selected);

    if (selectedCourses.length === 0) {
      alert('Please select at least one course to withdraw');
      return;
    }

    if (!agreedToTerms) {
      alert('Please read and agree to the terms and conditions');
      return;
    }

    if (isUnderMinimum) {
      alert(`Warning: After withdrawal, you will have ${creditsAfterWithdrawal} credits, which is below the minimum requirement of ${minimumRequiredCredits} credits. This may affect your academic standing.`);
      return;
    }

    // Double confirmation popup
    const courseList = selectedCourses.map(c => `${c.courseId} - ${c.courseName}`).join('\n');
    const confirmed = window.confirm(
      `⚠️ FINAL CONFIRMATION\n\nYou are about to withdraw from ${selectedCourses.length} course(s):\n\n${courseList}\n\nTotal Credits to Withdraw: ${withdrawalCredits}\nCredits After Withdrawal: ${creditsAfterWithdrawal}\n\nThis action cannot be undone. Do you wish to proceed?`
    );

    if (confirmed) {
      alert('Course withdrawal request submitted successfully!');
      // Reset form
      setCourses(courses.map(c => ({ ...c, selected: false })));
      setAgreedToTerms(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const badges = {
      'Pending': 'bg-yellow-100 text-yellow-800',
      'Approved': 'bg-green-100 text-green-800',
      'Rejected': 'bg-red-100 text-red-800',
    };
    return badges[status as keyof typeof badges] || 'bg-gray-100 text-gray-800';
  };

  return (
    <div className="p-6 space-y-6">
      {/* Page Header */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
        <h1 className="text-gray-800 mb-2">Course Withdrawal Request</h1>
        <p className="text-sm text-gray-600">
          Submit a formal request to withdraw from registered courses
        </p>
      </div>

      {/* Real-time Credit Calculator - Floating Summary */}
      <div className="bg-gradient-to-r from-blue-50 to-cyan-50 rounded-xl border border-blue-200 p-5 shadow-sm">
        <div className="flex items-start gap-4">
          <div className="w-12 h-12 bg-[#1488db] rounded-full flex items-center justify-center flex-shrink-0">
            <Calculator className="text-white" size={24} />
          </div>
          <div className="flex-1">
            <h3 className="text-gray-800 mb-3">Credit Calculation Summary</h3>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="bg-white rounded-lg p-4 border border-gray-200">
                <p className="text-xs text-gray-600 mb-1">Current Enrolled Credits</p>
                <p className="text-2xl text-gray-800">{currentEnrolledCredits}</p>
              </div>
              <div className="bg-white rounded-lg p-4 border border-gray-200">
                <p className="text-xs text-gray-600 mb-1">Credits to Withdraw</p>
                <p className="text-2xl text-orange-600">-{withdrawalCredits}</p>
              </div>
              <div className={`rounded-lg p-4 border-2 ${
                isUnderMinimum 
                  ? 'bg-red-50 border-red-300' 
                  : 'bg-green-50 border-green-300'
              }`}>
                <p className="text-xs text-gray-600 mb-1">Credits After Withdrawal</p>
                <p className={`text-2xl ${
                  isUnderMinimum ? 'text-red-600' : 'text-green-600'
                }`}>
                  {creditsAfterWithdrawal}
                </p>
                {isUnderMinimum && (
                  <p className="text-xs text-red-600 mt-1">⚠️ Below minimum ({minimumRequiredCredits})</p>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Section 1: Course Selection Grid */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
        <div className="flex items-center gap-3 mb-6">
          <div className="w-8 h-8 rounded-full bg-[#1488db] text-white flex items-center justify-center">
            1
          </div>
          <h2 className="text-gray-800">1. Select Courses for Withdrawal</h2>
        </div>

        {/* Course Selection Table */}
        <div className="overflow-x-auto">
          <table className="w-full min-w-[700px]">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                <th className="px-4 py-3 text-left text-sm text-gray-700 w-12">
                  <input
                    type="checkbox"
                    onChange={(e) => {
                      const isChecked = e.target.checked;
                      setCourses(courses.map(c => ({ ...c, selected: isChecked })));
                    }}
                    checked={courses.every(c => c.selected)}
                    className="w-4 h-4 text-orange-600 border-gray-300 rounded focus:ring-orange-500 cursor-pointer"
                  />
                </th>
                <th className="px-4 py-3 text-left text-sm text-gray-700">#</th>
                <th className="px-4 py-3 text-left text-sm text-gray-700">Course ID</th>
                <th className="px-4 py-3 text-left text-sm text-gray-700">Course Name</th>
                <th className="px-4 py-3 text-left text-sm text-gray-700">Credits</th>
                <th className="px-4 py-3 text-left text-sm text-gray-700">Group/Class</th>
              </tr>
            </thead>
            <tbody>
              {courses.map((course, index) => (
                <tr 
                  key={course.id} 
                  className={`border-b border-gray-100 hover:bg-orange-50 transition-colors ${
                    course.selected ? 'bg-orange-50' : ''
                  }`}
                >
                  <td className="px-4 py-3">
                    <input
                      type="checkbox"
                      checked={course.selected}
                      onChange={() => toggleCourseSelection(course.id)}
                      className="w-4 h-4 text-orange-600 border-gray-300 rounded focus:ring-orange-500 cursor-pointer"
                    />
                  </td>
                  <td className="px-4 py-3 text-sm text-gray-800">{index + 1}</td>
                  <td className="px-4 py-3 text-sm text-gray-800 font-medium">{course.courseId}</td>
                  <td className="px-4 py-3 text-sm text-gray-800">{course.courseName}</td>
                  <td className="px-4 py-3 text-sm text-gray-800">{course.credits}</td>
                  <td className="px-4 py-3 text-sm text-gray-600">{course.group}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Selected Summary */}
        <div className="mt-4 text-sm text-gray-600">
          Selected for withdrawal: <span className="font-medium text-gray-800">{courses.filter(c => c.selected).length}</span> course(s)
          {courses.filter(c => c.selected).length > 0 && (
            <span className="ml-2">
              ({withdrawalCredits} credit{withdrawalCredits !== 1 ? 's' : ''})
            </span>
          )}
        </div>
      </div>

      {/* Section 2: Student Commitment & Warning */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
        <div className="flex items-center gap-3 mb-6">
          <div className="w-8 h-8 rounded-full bg-[#1488db] text-white flex items-center justify-center">
            2
          </div>
          <h2 className="text-gray-800">2. Student Commitment & Terms</h2>
        </div>

        {/* Commitment Panel - Warning Orange */}
        <div className="border-l-4 border-orange-500 bg-gradient-to-r from-orange-50 to-yellow-50 rounded-r-lg p-6">
          <div className="flex gap-4">
            <AlertTriangle className="text-orange-500 flex-shrink-0 mt-1" size={24} />
            <div className="flex-1">
              <h3 className="text-gray-800 mb-4">Important Commitment</h3>

              <div className="space-y-3 mb-5">
                <div className="flex gap-3 text-sm text-gray-700">
                  <span className="text-orange-500 font-bold flex-shrink-0">•</span>
                  <p>
                    I commit to maintaining the minimum required credits after withdrawal. 
                    The university requires students to be enrolled in at least <strong>{minimumRequiredCredits} credits</strong> per semester to maintain full-time student status.
                  </p>
                </div>
                <div className="flex gap-3 text-sm text-gray-700">
                  <span className="text-orange-500 font-bold flex-shrink-0">•</span>
                  <p>
                    I agree to fulfill all tuition obligations, including fees for withdrawn courses. 
                    <strong> Withdrawal does not guarantee a tuition refund</strong>, and fees may still apply based on the withdrawal date.
                  </p>
                </div>
                <div className="flex gap-3 text-sm text-gray-700">
                  <span className="text-orange-500 font-bold flex-shrink-0">•</span>
                  <p>
                    I understand that course withdrawal may affect my academic progress, scholarship eligibility, and graduation timeline. 
                    Students should consult with their academic advisor before submitting this request.
                  </p>
                </div>
                <div className="flex gap-3 text-sm text-gray-700">
                  <span className="text-orange-500 font-bold flex-shrink-0">•</span>
                  <p>
                    I acknowledge that withdrawn courses will appear on my academic transcript with a 'W' grade. 
                    Multiple withdrawals may impact my academic standing.
                  </p>
                </div>
              </div>

              {/* Policy Link */}
              <div className="mb-5 pb-5 border-b border-orange-200">
                <a 
                  href="#" 
                  className="inline-flex items-center gap-2 text-sm text-[#1488db] hover:text-[#032b91] font-medium"
                >
                  <ExternalLink size={16} />
                  View Course Withdrawal Regulations & Policies
                </a>
              </div>

              {/* Agreement Checkbox */}
              <div className="flex items-start gap-3 p-4 bg-white rounded-lg border-2 border-orange-300">
                <input
                  type="checkbox"
                  id="terms-agreement"
                  checked={agreedToTerms}
                  onChange={(e) => setAgreedToTerms(e.target.checked)}
                  className="w-5 h-5 text-orange-600 border-gray-300 rounded focus:ring-orange-500 cursor-pointer mt-0.5 flex-shrink-0"
                />
                <label htmlFor="terms-agreement" className="text-sm text-gray-800 cursor-pointer select-none">
                  <strong>I have read and agree to all terms above.</strong> I understand the consequences of course withdrawal and take full responsibility for this decision.
                </label>
              </div>
            </div>
          </div>
        </div>

        {/* Confirm Button */}
        <div className="mt-6">
          <button
            type="button"
            onClick={handleConfirmWithdrawal}
            disabled={!agreedToTerms || courses.filter(c => c.selected).length === 0}
            className={`px-6 py-3 rounded-lg transition-all duration-200 flex items-center gap-2 ${
              agreedToTerms && courses.filter(c => c.selected).length > 0
                ? 'bg-[#032b91] hover:bg-[#1488db] text-white cursor-pointer'
                : 'bg-gray-300 text-gray-500 cursor-not-allowed'
            }`}
          >
            <Check size={18} />
            Confirm Withdrawal Request
          </button>
          {!agreedToTerms && courses.filter(c => c.selected).length > 0 && (
            <p className="mt-2 text-sm text-orange-600">
              ⚠️ Please read and agree to the terms before confirming
            </p>
          )}
        </div>
      </div>

      {/* Section 3: Withdrawal History */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
        <div className="flex items-center gap-3 mb-6">
          <div className="w-8 h-8 rounded-full bg-[#1488db] text-white flex items-center justify-center">
            3
          </div>
          <h2 className="text-gray-800">3. Withdrawal History</h2>
        </div>

        {records.length === 0 ? (
          <div className="text-center py-12">
            <p className="text-gray-500 text-sm">No withdrawal requests found</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[800px]">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="px-4 py-3 text-left text-sm text-gray-700">#</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Request ID</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Course Details</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Credits</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Submission Date</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Status</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Actions</th>
                </tr>
              </thead>
              <tbody>
                {records.map((record, index) => (
                  <tr key={record.id} className="border-b border-gray-100 hover:bg-gray-50">
                    <td className="px-4 py-3 text-sm text-gray-800">{index + 1}</td>
                    <td className="px-4 py-3 text-sm text-gray-800 font-medium">{record.requestId}</td>
                    <td className="px-4 py-3 text-sm text-gray-800">{record.courseDetails}</td>
                    <td className="px-4 py-3 text-sm text-gray-800">{record.credits}</td>
                    <td className="px-4 py-3 text-sm text-gray-600">{record.submissionDate}</td>
                    <td className="px-4 py-3">
                      <span className={`inline-block px-3 py-1 rounded text-sm ${getStatusBadge(record.status)}`}>
                        {record.status}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      {record.status === 'Approved' && (
                        <button
                          type="button"
                          className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-green-600 hover:bg-green-50 rounded transition-colors"
                          title="Download Confirmation PDF"
                        >
                          <Download size={14} />
                          PDF
                        </button>
                      )}
                      {record.status === 'Pending' && (
                        <span className="text-xs text-gray-500">Processing...</span>
                      )}
                      {record.status === 'Rejected' && (
                        <span className="text-xs text-red-600">Contact Office</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Safety Information Footer */}
      <div className="bg-blue-50 border-l-4 border-[#1488db] rounded-r-lg p-4">
        <div className="flex gap-3">
          <Info className="text-[#1488db] flex-shrink-0 mt-0.5" size={20} />
          <div className="text-sm text-gray-700">
            <p>
              <strong>Need Help?</strong> If you have questions about course withdrawal, contact the Academic Affairs Office at{' '}
              <strong>daotao@hcmut.edu.vn</strong> or visit the office during working hours (Mon-Fri, 7:30-11:30 & 13:00-16:30).
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, Fragment, useRef } from "react";
import {
  Info,
  Upload,
  X,
  Check,
  ChevronDown,
  Eye,
  FileText,
  Printer,
  AlertCircle,
} from "lucide-react";
import { Listbox, Transition } from "@headlessui/react";
import degreeExampleImage from "@/components/assets/bang_thpt.png";

interface DegreeRecord {
  id: number;
  recordId: string;
  content: string;
  status:
    | "Pending Verification"
    | "Under Review"
    | "Verified"
    | "Rejected - Re-upload required";
  submissionDate: string;
}

interface UploadedFile {
  id: string;
  name: string;
  size: number;
  preview?: string;
  type: string;
}

export function DegreeInformationDeclaration() {
  const [formData, setFormData] = useState({
    fullName: "TRAN NGUYEN KHANG",
    studentId: "2550299",
    dateOfBirth: "06/09/2007",
    placeOfBirth: "Ho Chi Minh City",
    identityDocument: "049207013849",
    email: "khang.tranngao9@hcmut.edu.vn",
    phoneNumber: "0938313117",
  });

  const [degreeData, setDegreeData] = useState({
    referenceNumber: "",
    registrationNumber: "",
    graduationDate: "",
    graduationYear: "",
  });

  const degreeTypes = [
    { id: 0, name: "-- Choose/select --" },
    { id: 1, name: "High School Graduation Certificate (Original)" },
    { id: 2, name: "High School Graduation Certificate (Certified Copy)" },
    { id: 3, name: "Equivalent Certificate (International)" },
  ];

  const issuingAuthorities = [
    { id: 0, name: "-- Choose/select --" },
    { id: 1, name: "Department of Education and Training of Ho Chi Minh City" },
    { id: 2, name: "Department of Education and Training of Hanoi" },
    { id: 3, name: "Department of Education and Training of Da Nang" },
    { id: 4, name: "Department of Education and Training of Binh Duong" },
    { id: 5, name: "Department of Education and Training of Dong Nai" },
  ];

  const [selectedDegreeType, setSelectedDegreeType] = useState(degreeTypes[0]);
  const [selectedAuthority, setSelectedAuthority] = useState(
    issuingAuthorities[0],
  );
  const [uploadedFile, setUploadedFile] = useState<UploadedFile | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [records] = useState<DegreeRecord[]>([
    {
      id: 1,
      recordId: "DID2025120001",
      content: "High School Graduation Certificate Declaration",
      status: "Verified",
      submissionDate: "15/12/2025",
    },
    {
      id: 2,
      recordId: "DID2025090023",
      content: "High School Graduation Certificate Declaration",
      status: "Under Review",
      submissionDate: "10/09/2025",
    },
  ]);

  const handleDegreeDataChange = (field: string, value: string) => {
    setDegreeData({ ...degreeData, [field]: value });
  };

  const handleFileSelect = (files: FileList | null) => {
    if (!files || files.length === 0) return;

    const file = files[0];

    // Check file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      alert(`File ${file.name} exceeds 5MB limit`);
      return;
    }

    // Check file type
    const validTypes = ["image/jpeg", "image/png", "application/pdf"];
    if (!validTypes.includes(file.type)) {
      alert(`File ${file.name} is not a supported format (JPG, PNG, PDF only)`);
      return;
    }

    const newFile: UploadedFile = {
      id: Math.random().toString(36).substr(2, 9),
      name: file.name,
      size: file.size,
      type: file.type,
    };

    // Create preview for images
    if (file.type.startsWith("image/")) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setUploadedFile({
          ...newFile,
          preview: e.target?.result as string,
        });
      };
      reader.readAsDataURL(file);
    } else {
      setUploadedFile(newFile);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    handleFileSelect(e.dataTransfer.files);
  };

  const removeFile = () => {
    setUploadedFile(null);
  };

  const formatFileSize = (bytes: number) => {
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
    return (bytes / (1024 * 1024)).toFixed(1) + " MB";
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (selectedDegreeType.id === 0 || selectedAuthority.id === 0) {
      alert("Please select degree type and issuing authority");
      return;
