      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Section 1: Personal Information (Read-only) */}
        <div className="rounded-xl border border-gray-200 bg-white p-6 shadow-sm">
          <div className="mb-6 flex items-center gap-3">
