            {/* Certificate Type - Searchable Dropdown */}
            <div>
              <label className="text-sm text-gray-700 mb-2 block">
                Certificate Type <span className="text-red-500">*</span>
              </label>
              <Listbox value={selectedCertificateType} onChange={setSelectedCertificateType}>
                <div className="relative">
                  <Listbox.Button className="relative w-full px-4 py-2.5 bg-white border border-gray-300 rounded-lg text-sm text-left focus:outline-none focus:border-[#1488db] focus:ring-1 focus:ring-[#1488db] hover:border-gray-400 transition-all cursor-pointer">
                    <span className={`block truncate ${selectedCertificateType.id === 0 ? 'text-gray-400' : 'text-gray-800'}`}>
                      {selectedCertificateType.name}
                    </span>
                    <span className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-3">
                      <ChevronDown className="h-4 w-4 text-gray-400" aria-hidden="true" />
                    </span>
                  </Listbox.Button>
                  <Transition
                    as={Fragment}
                    leave="transition ease-in duration-100"
                    leaveFrom="opacity-100"
                    leaveTo="opacity-0"
                  >
                    <Listbox.Options className="absolute z-10 mt-1 max-h-60 w-full overflow-auto rounded-lg bg-white py-1 shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none text-sm">
                      {certificateTypes.map((type) => (
                        <Listbox.Option
                          key={type.id}
                          className={({ active }) =>
                            `relative cursor-pointer select-none py-2.5 pl-10 pr-4 ${
                              active ? 'bg-[#1488db] text-white' : type.id === 0 ? 'text-gray-400' : 'text-gray-800'
                            }`
                          }
                          value={type}
                          disabled={type.id === 0}
                        >
                          {({ selected, active }) => (
                            <>
                              <span className={`block truncate ${selected ? 'font-medium' : 'font-normal'}`}>
                                {type.name}
                              </span>
                              {selected && type.id !== 0 ? (
                                <span
                                  className={`absolute inset-y-0 left-0 flex items-center pl-3 ${
                                    active ? 'text-white' : 'text-[#1488db]'
                                  }`}
                                >
                                  <Check className="h-4 w-4" aria-hidden="true" />
                                </span>
                              ) : null}
                            </>
                          )}
                        </Listbox.Option>
                      ))}
                    </Listbox.Options>
                  </Transition>
                </div>
              </Listbox>
            </div>

            {/* Certificate Details Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="text-sm text-gray-700 mb-2 block">
                  Candidate ID / ID Used for Test <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  value={certificateData.candidateId}
                  onChange={(e) => handleCertificateDataChange('candidateId', e.target.value)}
                  placeholder="Enter candidate ID"
                  required
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg text-sm text-gray-800 placeholder:text-gray-400 focus:outline-none focus:border-[#1488db] focus:ring-1 focus:ring-[#1488db] transition-all bg-white"
                />
              </div>

              <div>
                <label className="text-sm text-gray-700 mb-2 flex items-center gap-2">
                  Reference Number (Số hiệu) <span className="text-red-500">*</span>
                  <button
                    type="button"
                    onClick={() => setShowHelpModal(true)}
                    className="text-[#1488db] hover:text-[#032b91] transition-colors"
                    title="Help"
                  >
                    <HelpCircle size={16} />
                  </button>
                </label>
                <input
                  type="text"
                  value={certificateData.referenceNumber}
                  onChange={(e) => handleCertificateDataChange('referenceNumber', e.target.value)}
                  placeholder="Enter reference number"
                  required
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg text-sm text-gray-800 placeholder:text-gray-400 focus:outline-none focus:border-[#1488db] focus:ring-1 focus:ring-[#1488db] transition-all bg-white"
                />
              </div>

              <div>
                <label className="text-sm text-gray-700 mb-2 block">
                  Issue Date <span className="text-red-500">*</span>
                </label>
                <input
                  type="date"
                  value={certificateData.issueDate}
                  onChange={(e) => handleCertificateDataChange('issueDate', e.target.value)}
                  required
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg text-sm text-gray-800 focus:outline-none focus:border-[#1488db] focus:ring-1 focus:ring-[#1488db] transition-all bg-white"
                />
              </div>

              <div>
                <label className="text-sm text-gray-700 mb-2 block">
                  Level / Badge <span className="text-red-500">*</span>
                </label>
                <Listbox value={selectedLevel} onChange={setSelectedLevel}>
                  <div className="relative">
                    <Listbox.Button className="relative w-full px-4 py-2.5 bg-white border border-gray-300 rounded-lg text-sm text-left focus:outline-none focus:border-[#1488db] focus:ring-1 focus:ring-[#1488db] hover:border-gray-400 transition-all cursor-pointer">
                      <span className={`block truncate ${selectedLevel.id === 0 ? 'text-gray-400' : 'text-gray-800'}`}>
                        {selectedLevel.name}
                      </span>
                      <span className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-3">
                        <ChevronDown className="h-4 w-4 text-gray-400" aria-hidden="true" />
                      </span>
                    </Listbox.Button>
                    <Transition
                      as={Fragment}
                      leave="transition ease-in duration-100"
                      leaveFrom="opacity-100"
                      leaveTo="opacity-0"
                    >
                      <Listbox.Options className="absolute z-10 mt-1 max-h-60 w-full overflow-auto rounded-lg bg-white py-1 shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none text-sm">
                        {levelOptions.map((level) => (
                          <Listbox.Option
                            key={level.id}
                            className={({ active }) =>
                              `relative cursor-pointer select-none py-2.5 pl-10 pr-4 ${
                                active ? 'bg-[#1488db] text-white' : level.id === 0 ? 'text-gray-400' : 'text-gray-800'
                              }`
                            }
                            value={level}
                            disabled={level.id === 0}
                          >
                            {({ selected, active }) => (
                              <>
                                <span className={`block truncate ${selected ? 'font-medium' : 'font-normal'}`}>
                                  {level.name}
                                </span>
                                {selected && level.id !== 0 ? (
                                  <span
                                    className={`absolute inset-y-0 left-0 flex items-center pl-3 ${
                                      active ? 'text-white' : 'text-[#1488db]'
                                    }`}
                                  >
                                    <Check className="h-4 w-4" aria-hidden="true" />
                                  </span>
                                ) : null}
                              </>
                            )}
                          </Listbox.Option>
                        ))}
                      </Listbox.Options>
                    </Transition>
                  </div>
                </Listbox>
              </div>
            </div>

            {/* Skills Achieved - Multi-select with Combobox */}
            <div>
              <label className="text-sm text-gray-700 mb-2 block">
                Skills Achieved <span className="text-red-500">*</span>
              </label>
              <Combobox value={selectedSkills} onChange={setSelectedSkills} multiple>
                <div className="relative">
                  <div className="w-full border border-gray-300 rounded-lg bg-white focus-within:border-[#1488db] focus-within:ring-1 focus-within:ring-[#1488db] transition-all">
                    {/* Selected Skills Tags */}
                    <div className="flex flex-wrap gap-2 px-3 py-2 min-h-[42px]">
                      {selectedSkills.map((skill) => (
                        <span
                          key={skill.id}
                          className="inline-flex items-center gap-1.5 px-3 py-1 bg-[#1488db] text-white rounded text-sm"
                        >
                          {skill.name}
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              removeSkill(skill.id);
                            }}
                            className="hover:bg-white/20 rounded-full p-0.5"
                          >
                            <X size={14} />
                          </button>
                        </span>
                      ))}
                      <Combobox.Input
                        className="flex-1 min-w-[120px] outline-none text-sm text-gray-800 placeholder:text-gray-400"
                        placeholder={selectedSkills.length === 0 ? "Search and select skills..." : ""}
                        onChange={(event) => setSkillQuery(event.target.value)}
                        displayValue={() => ''}
                      />
                    </div>
                  </div>
                  <Transition
                    as={Fragment}
                    leave="transition ease-in duration-100"
                    leaveFrom="opacity-100"
                    leaveTo="opacity-0"
                    afterLeave={() => setSkillQuery('')}
                  >
                    <Combobox.Options className="absolute z-10 mt-1 max-h-60 w-full overflow-auto rounded-lg bg-white py-1 shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none text-sm">
                      {filteredSkills.length === 0 && skillQuery !== '' ? (
                        <div className="relative cursor-default select-none py-2 px-4 text-gray-700">
                          No skills found.
                        </div>
                      ) : (
                        filteredSkills.map((skill) => (
                          <Combobox.Option
                            key={skill.id}
                            className={({ active }) =>
                              `relative cursor-pointer select-none py-2.5 pl-10 pr-4 ${
                                active ? 'bg-[#1488db] text-white' : 'text-gray-800'
                              }`
                            }
                            value={skill}
                          >
                            {({ selected, active }) => (
                              <>
                                <span className={`block truncate ${selected ? 'font-medium' : 'font-normal'}`}>
                                  {skill.name}
                                </span>
                                {selected ? (
                                  <span
                                    className={`absolute inset-y-0 left-0 flex items-center pl-3 ${
                                      active ? 'text-white' : 'text-[#1488db]'
                                    }`}
                                  >
                                    <Check className="h-4 w-4" aria-hidden="true" />
                                  </span>
                                ) : null}
                              </>
                            )}
                          </Combobox.Option>
                        ))
                      )}
                    </Combobox.Options>
                  </Transition>
                </div>
              </Combobox>
              <p className="mt-1.5 text-xs text-gray-500">
                Click or search to add multiple skills. {selectedSkills.length} skill{selectedSkills.length !== 1 ? 's' : ''} selected.
              </p>
            </div>
          </div>
        </div>

        {/* Section 3: Evidence Management */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
          <div className="flex items-center gap-3 mb-6">
            <div className="w-8 h-8 rounded-full bg-[#1488db] text-white flex items-center justify-center">
              3
            </div>
            <h2 className="text-gray-800">3. Upload Certificate Document</h2>
          </div>

          <div
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`border-2 border-dashed rounded-lg p-8 text-center transition-all ${
              isDragging
                ? 'border-[#1488db] bg-blue-50'
                : 'border-gray-300 hover:border-gray-400 bg-gray-50'
            }`}
          >
            <div className="flex flex-col items-center gap-3">
              <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center">
                <Upload className="text-[#1488db]" size={32} />
              </div>
              <div>
                <p className="text-sm text-gray-800 mb-1">
                  Drag and drop your certificate file here, or{' '}
                  <button
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                    className="text-[#1488db] hover:text-[#032b91] font-medium"
                  >
                    browse
                  </button>
                </p>
                <p className="text-xs text-gray-500">
                  Supported formats: JPG, PNG, PDF (Maximum size: 5MB)
                </p>
              </div>
            </div>
            <input
              ref={fileInputRef}
              type="file"
              accept=".jpg,.jpeg,.png,.pdf"
              onChange={(e) => handleFileSelect(e.target.files)}
              className="hidden"
            />
          </div>

          {/* Uploaded File */}
          {uploadedFile && (
            <div className="mt-4 border border-gray-200 rounded-lg p-4 bg-white">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 bg-blue-100 rounded flex items-center justify-center">
                    <FileText className="text-[#1488db]" size={24} />
                  </div>
                  <div>
                    <p className="text-sm text-gray-800 truncate">{uploadedFile.name}</p>
                    <p className="text-xs text-gray-500">{formatFileSize(uploadedFile.size)}</p>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={removeFile}
                  className="w-8 h-8 bg-red-500 hover:bg-red-600 text-white rounded-full flex items-center justify-center transition-colors"
                >
                  <X size={16} />
                </button>
              </div>
            </div>
          )}

          {/* Important Notice */}
          <div className="mt-4 flex gap-2 p-3 bg-blue-50 border-l-4 border-[#1488db] rounded-r-lg">
            <Info className="text-[#1488db] flex-shrink-0 mt-0.5" size={16} />
            <p className="text-xs text-gray-700">
              <strong>Important:</strong> Please upload a clear, high-quality scan or digital copy of your IT certificate. 
              The document must show the certificate holder's name, issue date, reference number, and official seal/signature.
            </p>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex gap-3 justify-end">
          <button
            type="button"
            onClick={() => window.open('#', '_blank')}
            className="px-6 py-2.5 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg transition-all duration-200 flex items-center gap-2"
          >
            <BookOpen size={18} />
            View Guide
          </button>
          <button
            type="submit"
            className="px-6 py-2.5 bg-[#032b91] hover:bg-[#1488db] text-white rounded-lg transition-all duration-200 flex items-center gap-2"
          >
            <Check size={18} />
            Submit Declaration
          </button>
        </div>
      </form>

      {/* Section 4: IT Certificate Status Dashboard */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
        <div className="flex items-center gap-3 mb-6">
          <div className="w-8 h-8 rounded-full bg-[#1488db] text-white flex items-center justify-center">
            4
          </div>
          <h2 className="text-gray-800">4. IT Certificate Status Dashboard</h2>
        </div>

        {records.length === 0 ? (
          <div className="text-center py-12">
            <p className="text-gray-500 text-sm">No certificate declarations found</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[800px]">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="px-4 py-3 text-left text-sm text-gray-700">#</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Certificate Type</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">ID Number</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Submission Date</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Verification Status</th>
                  <th className="px-4 py-3 text-left text-sm text-gray-700">Actions</th>
                </tr>
              </thead>
              <tbody>
                {records.map((record, index) => (
                  <tr key={record.id} className="border-b border-gray-100 hover:bg-gray-50">
                    <td className="px-4 py-3 text-sm text-gray-800">{index + 1}</td>
                    <td className="px-4 py-3 text-sm text-gray-800">{record.certificateType}</td>
                    <td className="px-4 py-3 text-sm text-gray-800 font-medium">{record.idNumber}</td>
                    <td className="px-4 py-3 text-sm text-gray-600">{record.submissionDate}</td>
                    <td className="px-4 py-3">
                      <span className={`inline-block px-3 py-1 rounded text-sm ${getStatusBadge(record.status)}`}>
                        {record.status}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-2">
                        <button
                          type="button"
                          className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-[#1488db] hover:bg-blue-50 rounded transition-colors"
                          title="View Details"
                        >
                          <Eye size={14} />
                          View
                        </button>
                        {record.status === 'Verified' && (
                          <button
                            type="button"
                            className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-green-600 hover:bg-green-50 rounded transition-colors"
                            title="Download Certificate"
                          >
                            <Download size={14} />
                            PDF
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Help Modal */}
      <Transition appear show={showHelpModal} as={Fragment}>
        <Dialog as="div" className="relative z-50" onClose={() => setShowHelpModal(false)}>
          <Transition.Child
            as={Fragment}
            enter="ease-out duration-300"
            enterFrom="opacity-0"
            enterTo="opacity-100"
            leave="ease-in duration-200"
            leaveFrom="opacity-100"
            leaveTo="opacity-0"
          >
            <div className="fixed inset-0 bg-black bg-opacity-25" />
          </Transition.Child>

          <div className="fixed inset-0 overflow-y-auto">
            <div className="flex min-h-full items-center justify-center p-4 text-center">
              <Transition.Child
                as={Fragment}
                enter="ease-out duration-300"
                enterFrom="opacity-0 scale-95"
                enterTo="opacity-100 scale-100"
                leave="ease-in duration-200"
                leaveFrom="opacity-100 scale-100"
                leaveTo="opacity-0 scale-95"
              >
                <Dialog.Panel className="w-full max-w-md transform overflow-hidden rounded-2xl bg-white p-6 text-left align-middle shadow-xl transition-all">
                  <Dialog.Title className="flex items-center gap-2 text-gray-800 mb-4">
                    <HelpCircle className="text-[#1488db]" size={24} />
                    How to Find Your Reference Number?
                  </Dialog.Title>
                  <div className="mt-2 space-y-3 text-sm text-gray-700">
                    <p>
                      The <strong>Reference Number (Số hiệu)</strong> is a unique identifier printed on your IT certificate. 
                      Here's how to locate it:
                    </p>
                    <ul className="list-disc list-inside space-y-2 ml-2">
                      <li>
                        <strong>MOS Certificates:</strong> Look for a code starting with "MOS-" followed by numbers, 
                        usually located in the top-right corner or bottom of the certificate.
                      </li>
                      <li>
                        <strong>IC3 Certificates:</strong> The reference number appears as "IC3-" followed by your 
                        test year and unique digits, typically near the seal.
                      </li>
                      <li>
                        <strong>Other Certificates:</strong> Check the bottom section or back side of your certificate 
                        for a serial number or document ID.
                      </li>
                    </ul>
                    <p className="text-xs text-gray-600 bg-blue-50 p-3 rounded">
                      💡 <strong>Tip:</strong> If you cannot locate the reference number, contact the issuing organization 
                      or check your digital certificate email confirmation.
                    </p>
                  </div>

                  <div className="mt-6">
                    <button
                      type="button"
                      className="w-full px-4 py-2 bg-[#1488db] hover:bg-[#032b91] text-white rounded-lg transition-colors"
                      onClick={() => setShowHelpModal(false)}
                    >
                      Got it, thanks!
                    </button>
                  </div>
                </Dialog.Panel>
              </Transition.Child>
            </div>
          </div>
        </Dialog>
      </Transition>
    </div>
  );
}
